def isValidBST(root: Optional[TreeNode]) -> bool:
    def get_all_values(node, vals):
        if not node:
            return
        get_all_values(node.left, vals)
        vals.append(node.val)
        get_all_values(node.right, vals)

    vals = []
    get_all_values(root, vals)
    for i in range(1, len(vals)):
        if vals[i] <= vals[i-1]:
            return False
    return True

