def generate(rng, n):
    if n <= 0:
        return [None]
    vals = list(range(1, n + 1))
    rng.shuffle(vals)
    def insert_level_order(arr):
        if not arr:
            return None
        from collections import deque
        root = TreeNode(arr[0])
        queue = deque([root])
        i = 1
        while queue and i < len(arr):
            curr = queue.popleft()
            if i < len(arr) and arr[i] is not None:
                curr.left = TreeNode(arr[i])
                queue.append(curr.left)
            i += 1
            if i < len(arr) and arr[i] is not None:
                curr.right = TreeNode(arr[i])
                queue.append(curr.right)
            i += 1
        return root
    return [insert_level_order(vals)]

def generate_worst(rng, n):
    if n <= 0:
        return [None]
    vals = list(range(n))
    def build_skewed(arr):
        if not arr:
            return None
        root = TreeNode(arr[0])
        curr = root
        for v in arr[1:]:
            curr.right = TreeNode(v)
            curr = curr.right
        return root
    return [build_skewed(vals)]

